/* 
*/  
/*[INTERNET APPENDIX IA-11] FIGURE IA-13*/
/* 
*/ 

PROC SORT DATA = Mining_Regions; BY YEAR;
RUN;

data fig; set Mining_Regions;
if iv_cov_country = 0 then iv_noncov_country = 1; else iv_noncov_country = 0;
if iv_noncov_country = 1 then DRoC = 0;
run;

PROC SORT DATA = fig; BY YEAR;
RUN;

PROC MEANS data=fig mean MAXDEC=2;
class iv_cov_country;
   var     
 		 dv_cell_dum_conflict;
         BY YEAR;
         output out = figure;
RUN;

data figure; set figure;
	if iv_cov_country = . then delete;
	if _STAT_ = 'N' then delete;
	if _STAT_ = 'MIN' then delete;
	if _STAT_ = 'MAX' then delete;
	if _STAT_ = 'STD' then delete;
	drop _TYPE_ _FREQ_ _STAT_;
	if iv_cov_country = 0 then non_cov_con = 1;

   dv_cell_dum_c_x_cc                = dv_cell_dum_conflict*iv_cov_country;
   dv_cell_dum_c_x_nc                = dv_cell_dum_conflict*non_cov_con;

   if dv_cell_dum_c_x_cc = 0 then dv_cell_dum_c_x_cc = .;
run;

goptions reset=all ftext='Serif' htext=1.8 ;
symbol1 interpol=join line=33 width=4 H=3 c=TEAL;
symbol2 interpol=join line=1 width=3 H=3 c=black;
axis1 label=(angle=90 "Conflict Dummy") MINOR=NONE order=(.00 to .4 by .1);
axis2       label=("Year") MINOR=NONE order=(2010 to 2019 by 1);
legend1 LABEL=NONE value=("Non-Covered Countries") across=1 down=1 position=(bottom center  outside);
legend2 LABEL=NONE value=("Covered Countries") across=1 down=1 position=(bottom center outside);

PROC GPLOT DATA = Figure;
PLOT dv_cell_dum_c_x_nc*YEAR/haxis=axis2 vaxis=axis1 LHREF=20 HREF=2014 LEGEND=LEGEND1;
PLOT2 dv_cell_dum_c_x_cc*YEAR/OVERLAY haxis=axis2 vaxis=axis1 LEGEND=LEGEND2;
run;

